<script setup lang="ts">
import ArticleCard from '~/components/news/ArticleCard.vue'

useSeoMeta({ title: 'News | Alumni Portal', description: 'Alumni news, achievements, and announcements.' })

const { fetchArticles, fetchCategories } = useNews()

const selectedCategory = ref<number | null>(null)
const currentPage = ref(1)
const categories = ref<{ label: string, value: number | null }[]>([])

const catList = await fetchCategories()
categories.value = [
  { label: 'All', value: null },
  ...catList.map(c => ({ label: c.name, value: c.id })),
]

const { data: articles, refresh, pending } = await useAsyncData('news', () =>
  fetchArticles({ categoryId: selectedCategory.value || undefined, page: currentPage.value }),
)

watch(selectedCategory, () => {
  currentPage.value = 1
  refresh()
})
</script>

<template>
  <div>
    <div class="bg-white border-b border-slate-200 py-8 px-4">
      <div class="max-w-6xl mx-auto">
        <h1 class="text-2xl font-bold text-slate-900">News & Updates</h1>
        <div class="flex gap-2 mt-4 flex-wrap">
          <button
            v-for="cat in categories"
            :key="String(cat.value)"
            class="px-3 py-1.5 text-sm font-medium rounded-full transition-colors"
            :class="selectedCategory === cat.value ? 'bg-primary-600 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'"
            @click="selectedCategory = cat.value"
          >
            {{ cat.label }}
          </button>
        </div>
      </div>
    </div>

    <div class="max-w-6xl mx-auto px-4 py-8">
      <div v-if="pending" class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
        <div v-for="i in 6" :key="i" class="bg-white border border-slate-200 rounded-xl h-64 animate-pulse" />
      </div>
      <div v-else-if="articles && articles.length > 0" class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
        <ArticleCard v-for="article in articles" :key="article.id" :article="article" />
      </div>
      <div v-else class="text-center py-16">
        <i class="pi pi-megaphone text-4xl text-slate-300 mb-3 block" />
        <p class="text-slate-500">No articles found</p>
      </div>
    </div>
  </div>
</template>
